xql_query:
// ============================================================
// Rule: THM_Suspicious ICACLS Permissions Deny
// Vendor: Windows
// Objective:
// Detect activity associated with THM_Suspicious ICACLS Permissions Deny.
// Severity: SEV_050_CRITICAL
// Category: DROPPER
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0005 - Defense Evasion
// Technique: T1222.002 - File and Directory Permissions Modification: Linux and Mac File and Directory Permissions Modification
// Technique: T1222.001 - File and Directory Permissions Modification: Windows File and Directory Permissions Modification

dataset = xdr_data
| filter
    // Apenas endpoints Windows
    agent_os_type = ENUM.AGENT_OS_WINDOWS
    // Somente eventos de processo (início/fim)
    and event_type   = ENUM.PROCESS
    and event_sub_type in (ENUM.PROCESS_START, ENUM.PROCESS_STOP)

// ===============================
// 2) Padrão de execução do icacls
//    - Foca no binário icacls.exe
//    - Detecta linha de comando com /deny ... :(DE,DC)
//      (negação de permissões Delete e DeleteChild)
// ===============================
| filter
    lowercase(action_process_image_name) = "icacls.exe"
    and lowercase(action_process_image_command_line) ~= "\/deny.*\:\(de,dc\)"

// ===============================
// 3) Projeção de campos úteis
//    - Contexto do processo-alvo (action_*)
//    - Usuários e cadeia causal (actor_*, causality_actor_*, os_actor_*)
//    - Artefatos para triagem (hash, file info, web mark, cwd, script)
// ===============================
| fields
    // Temporal e host
    _time,
    agent_hostname,

    // Processo que executou a ação (target/action)
    action_process_username,
    action_process_image_name,
    action_process_image_path,
    action_process_image_command_line,
    action_process_image_sha256,
    action_process_cwd,
    action_process_script,
    action_process_file_info,
    action_process_file_size,
    action_process_file_web_mark,

    // Processo ator imediato (parent)
    actor_effective_username,
    actor_process_image_name,
    actor_process_image_path,
    actor_process_image_command_line,
    actor_process_image_sha256,

    // Processo causal (ancestral na árvore causal)
    causality_actor_primary_username,
    causality_actor_process_image_name,
    causality_actor_process_image_path,
    causality_actor_process_command_line,
    causality_actor_process_image_sha256,

    // Processo ator segundo o SO (quando aplicável)
    os_actor_primary_username,
    os_actor_process_image_name,
    os_actor_process_image_path,
    os_actor_process_image_command_line,
    os_actor_process_image_sha256
